// middleware.js — Pantalla de acceso para gracielasalvador.com/bolsillo («Mi psicóloga en el bolsillo»)
// Va en la RAÍZ del proyecto (al lado de index.html principal), no dentro de /bolsillo.
// La dirección antigua /herramientas redirige a /bolsillo.
// La contraseña NO está aquí: se guarda en Vercel como variable de entorno HERRAMIENTAS_PASSWORD.

export const config = { matcher: ['/bolsillo', '/bolsillo/:path*', '/herramientas', '/herramientas/:path*'] };

const COOKIE = 'gs_acceso';
const DIAS = 90; // días que el dispositivo recuerda el acceso

async function huella(pass) {
  const data = new TextEncoder().encode('gs-herramientas:' + pass);
  const hash = await crypto.subtle.digest('SHA-256', data);
  return [...new Uint8Array(hash)].map(b => b.toString(16).padStart(2, '0')).join('');
}

function leerCookie(req, nombre) {
  const c = req.headers.get('cookie') || '';
  const m = c.match(new RegExp('(?:^|;\\s*)' + nombre + '=([^;]+)'));
  return m ? m[1] : null;
}

const continuar = () => new Response(null, { headers: { 'x-middleware-next': '1' } });

export default async function middleware(req) {
  const pass = process.env.HERRAMIENTAS_PASSWORD;
  if (!pass) return pantalla('Falta configurar la contraseña en Vercel.', 500);
  const valida = await huella(pass);
  const url = new URL(req.url);
  if (url.pathname === '/herramientas' || url.pathname.startsWith('/herramientas/')) return Response.redirect(new URL(url.pathname.replace(/^\/herramientas/, '/bolsillo') + url.search, url), 308);

  if (req.method === 'POST') {
    let escrita = '';
    try { escrita = String((await req.formData()).get('clave') || ''); } catch (e) {}
    if (escrita.trim() === pass) {
      return new Response(null, { status: 303, headers: {
        'Location': '/bolsillo/',
        'Set-Cookie': `${COOKIE}=${valida}; Path=/bolsillo; Max-Age=${DIAS * 86400}; HttpOnly; Secure; SameSite=Lax`,
        'Cache-Control': 'no-store' } });
    }
    return pantalla('La contraseña no es correcta. Revísala o pídesela a Graciela.', 401);
  }

  if (url.pathname === '/bolsillo') return Response.redirect(new URL('/bolsillo/' + url.search, url), 308);
  if (leerCookie(req, COOKIE) === valida) return continuar();
  return pantalla('', 401);
}

function pantalla(error, status) {
  const html = `<!doctype html><html lang="es"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="robots" content="noindex"><meta name="theme-color" content="#0F4C5C">
<title>Mi psicóloga en el bolsillo · Acceso</title>
<link rel="icon" type="image/png" href="data:image/png;base64,">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,500;1,500&family=Nunito+Sans:opsz,wght@6..12,400;6..12,700&display=swap">
<style>
:root{--bg:#F5F9F9;--surface:#FFFFFF;--ink:#17343B;--muted:#5C747A;--line:#D7E5E8;--accent:#166A7E;--deep:#0F4C5C;--tint:#E4EFF1;--on:#FFFFFF;--err:#8E4E33;--errbg:#F4E3DA}
@media (prefers-color-scheme:dark){:root{--bg:#0C1C21;--surface:#12282E;--ink:#E2EEF0;--muted:#9AB2B8;--line:#234046;--accent:#5FB2C3;--deep:#9AD3DE;--tint:#18343B;--on:#0C1C21;--err:#E8B39A;--errbg:#3A2A23;color-scheme:dark}}
*{box-sizing:border-box}html,body{margin:0;height:100%}
body{background:var(--bg);color:var(--ink);font-family:"Nunito Sans","Segoe UI",system-ui,sans-serif;display:grid;place-items:center;
 padding:24px max(16px,env(safe-area-inset-right,0px)) 24px max(16px,env(safe-area-inset-left,0px))}
main{width:100%;max-width:380px;background:var(--surface);border:1px solid var(--line);border-radius:26px;padding:32px 24px;display:flex;flex-direction:column;align-items:center;gap:14px;text-align:center}
.logo{width:76px;height:76px;border-radius:50%;background:#fff;display:grid;place-items:center;border:1px solid var(--line)}.logo img{width:60px}
.brand{font-size:.78rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}.brand b{color:var(--deep)}
h1{font-family:Lora,Georgia,serif;font-weight:500;color:var(--deep);font-size:1.7rem;margin:4px 0 0}
p{margin:0;color:var(--muted);line-height:1.5}
form{width:100%;display:flex;flex-direction:column;gap:10px;margin-top:6px}
input{width:100%;font:inherit;font-size:1.05rem;padding:14px;border-radius:14px;border:1.5px solid var(--line);background:var(--bg);color:var(--ink);text-align:center}
input:focus-visible,button:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
button{font:inherit;font-weight:700;font-size:1rem;border:0;border-radius:999px;padding:13px;background:var(--accent);color:var(--on);cursor:pointer}
.err{background:var(--errbg);color:var(--err);border-radius:12px;padding:10px 12px;font-size:.92rem;width:100%}
small{color:var(--muted);font-size:.82rem;line-height:1.45}
</style></head><body><main>
<div class="logo"><img src="data:image/png;base64," alt="Logo de Graciela Salvador"></div>
<div class="brand"><b>Graciela Salvador</b> · Psicóloga</div>
<h1>Mi psicóloga en el bolsillo</h1>
<p>Este espacio es para las personas que trabajan conmigo en terapia. Escribe la contraseña que te he dado.</p>
${error ? `<div class="err" role="alert">${error}</div>` : ''}
<form method="post" action="/bolsillo/">
<label for="clave" style="position:absolute;left:-9999px">Contraseña</label>
<input id="clave" name="clave" type="password" autocomplete="current-password" placeholder="Contraseña" required autofocus>
<button type="submit">Entrar</button>
</form>
<small>Este dispositivo recordará el acceso durante ${DIAS} días.</small>
</main></body></html>`;
  return new Response(html, { status, headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });
}

